void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 time =  vec2(cos(iTime), sin(iTime));
    vec2 uv = fragCoord/iResolution.xy;
    uv += 0.1*dot(time,uv);

    int nearest[] = int[](-1, -1, -1);
    float distn[] = float[](100.0,100.0,100.0);

    for (int i = 0; i < 10; i++)
    {
        float d = distance(uv, points[i]);
        int j;
        for (j = 0; j < 3; j++)
        {
            float distance_point = distance(uv.x-points[j].x,uv.y-points[j].y);
            if (d + 0.01*cos(30.*(1./d+iTime/10.)) < distn[j])
            {
                for (int k = 2; k > j; k--)
                {
                    nearest[k] = nearest[k-1];
                    distn[k] = distn[k-1];
                }
                nearest[j] = i;
                distn[j] = d;

                break;
            }
        }
    }


    // Time varying pixel color
    // vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));



    vec3 col = colors[nearest[0]]/distn[0] + colors[nearest[1]]/distn[1] + colors[nearest[2]]/distn[2];

    // Output to screen
    fragColor = vec4(col/(1./distn[0]+1./distn[1]+1./distn[2]),1.0);
}

